        q_norm.w = -q_norm.w;
        q_norm.x = -q_norm.x;
        q_norm.y = -q_norm.y;
        q_norm.z = -q_norm.z;
    }

    // Output accepted
    *accepted = q_norm;

    // Update history
    qc_state.previous = q_norm;
}

return ADCS_OK;

